-- Now that the encounters exist, mark the occupied beds. Doing this
-- as an UPDATE derived from the encounters - rather than as literals -
-- means the bed board and the patient list cannot disagree.
UPDATE beds b
   SET status = 'occupied',
       current_encounter_id = e.id,
       current_patient_id = e.patient_id
  FROM encounters e
 WHERE e.bed_id = b.id
   AND e.status IN ('in-progress', 'onleave');

