INSERT INTO clinical_notes (id, patient_id, encounter_id, type, title, body, author_name, author_role, created_at, updated_at, is_signed, language) VALUES ('note-0001', 'pat-001', 'enc-001', 'admission', 'Note d''admission - décompensation cardiaque', 'Patient de 77 ans, connu pour une insuffisance cardiaque à fraction d''éjection réduite, admis pour dyspnée croissante depuis cinq jours et prise de poids de 4 kg.
INSERT INTO clinical_notes (id, patient_id, encounter_id, type, title, body, author_name, author_role, created_at, updated_at, is_signed, language) VALUES ('note-0002', 'pat-001', 'enc-001', 'nursing', 'Suivi infirmier - pesée du matin', 'Poids ce matin 82,4 kg, soit -1,6 kg par rapport à hier. Diurèse des 24 h : 2 350 mL. Le patient se dit moins essoufflé, a pu marcher jusqu''à la salle de bain sans aide. Œdèmes en régression. SpO2 95 % à l''air ambiant.', 'Marie Lambert', 'Nurse', now() - interval '21600 seconds', NULL, true, 'fr');
INSERT INTO clinical_notes (id, patient_id, encounter_id, type, title, body, author_name, author_role, created_at, updated_at, is_signed, language) VALUES ('note-0003', 'pat-002', 'enc-002', 'admission', 'Opnamenotitie - pneumonie', 'Vrouw van 70 jaar, sinds vier dagen koorts tot 39,2 °C, productieve hoest met purulent sputum en pijn rechts thoracaal bij inademing.
INSERT INTO clinical_notes (id, patient_id, encounter_id, type, title, body, author_name, author_role, created_at, updated_at, is_signed, language) VALUES ('note-0004', 'pat-003', 'enc-003', 'progress', 'Post-operative day 1', 'Laparoscopic cholecystectomy performed yesterday without complications. Four ports, gallbladder removed intact, no drain left in place.
INSERT INTO clinical_notes (id, patient_id, encounter_id, type, title, body, author_name, author_role, created_at, updated_at, is_signed, language) VALUES ('note-0005', 'pat-008', 'enc-008', 'progress', 'Intensieve zorgen - dag 6', 'Urosepsis met septische shock bij opname. Noradrenaline sinds gisterochtend afgebouwd en nu gestopt. Hemodynamisch stabiel zonder vasopressoren.
INSERT INTO clinical_notes (id, patient_id, encounter_id, type, title, body, author_name, author_role, created_at, updated_at, is_signed, language) VALUES ('note-0006', 'pat-010', 'enc-010', 'nursing', 'Verpleegkundige observatie - nachtdienst', 'Noah heeft rustig geslapen, geen nachtelijke hoestbuien. Piekstroom bij het ontwaken 78% van de voorspelde waarde, tegenover 61% bij opname. Salbutamol viermaal gegeven volgens schema, geen extra doses nodig geweest.
INSERT INTO clinical_notes (id, patient_id, encounter_id, type, title, body, author_name, author_role, created_at, updated_at, is_signed, language) VALUES ('note-0007', 'pat-013', 'enc-013', 'progress', 'Revalidation - bilan hebdomadaire', 'Patiente de 89 ans en revalidation après fracture du col du fémur opérée il y a neuf jours.
INSERT INTO clinical_notes (id, patient_id, encounter_id, type, title, body, author_name, author_role, created_at, updated_at, is_signed, language) VALUES ('note-0008', 'pat-018', 'enc-018', 'progress', 'Équilibration du diabète - jour 3', 'Glycémies des dernières 24 h : 212, 178, 156, 143 mg/dL. Nette amélioration depuis l''introduction de l''insuline asparte avant les repas.
INSERT INTO clinical_notes (id, patient_id, encounter_id, type, title, body, author_name, author_role, created_at, updated_at, is_signed, language) VALUES ('note-0009', 'pat-005', 'enc-005', 'observation', 'Emergency triage note', 'Thirty-five year old woman presenting with central chest tightness that started two hours ago at rest, lasting about twenty minutes, now resolved. No radiation, no dyspnoea, no sweating.
INSERT INTO clinical_notes (id, patient_id, encounter_id, type, title, body, author_name, author_role, created_at, updated_at, is_signed, language) VALUES ('note-0010', 'pat-020', 'enc-020', 'progress', 'Suivi post-infarctus - jour 5', 'Patient de 75 ans, infarctus inférieur traité par angioplastie primaire avec pose d''un stent actif sur la coronaire droite.
INSERT INTO clinical_notes (id, patient_id, encounter_id, type, title, body, author_name, author_role, created_at, updated_at, is_signed, language) VALUES ('note-0011', 'pat-004', NULL, 'discharge', 'Ontslagbrief - pyelonefritis', 'Patiënte werd opgenomen met rechtszijdige flankpijn, koorts en dysurie. Diagnose: acute pyelonefritis rechts.
INSERT INTO clinical_notes (id, patient_id, encounter_id, type, title, body, author_name, author_role, created_at, updated_at, is_signed, language) VALUES ('note-0012', 'pat-016', 'enc-016', 'observation', 'Observation - douleur abdominale', 'Garçon de 15 ans, douleur abdominale péri-ombilicale depuis hier soir, migrant vers la fosse iliaque droite ce matin. Une vomissement, pas de diarrhée.
