INSERT INTO integration_flows (id, name, description, is_enabled, nodes, connections, updated_at, messages_processed, messages_failed) VALUES ('flow-mqtt-vitals', '{"en":"Bedside monitors to the record","fr":"Moniteurs de chevet vers le dossier","nl":"Bedmonitoren naar het dossier"}'::jsonb, '{"en":"The whole chain a hospital actually runs. A monitor publishes a measurement on MQTT, the engine decodes the device payload into an ORU^R01 - the message a real monitor sends - translates that to a FHIR Observation, and files it. Three formats, one reading, and every step visible on the trace.","fr":"La chaîne complète telle qu''un hôpital la fait tourner. Un moniteur publie une mesure en MQTT, le moteur décode la trame en ORU^R01 - le message qu''envoie un vrai moniteur - le traduit en Observation FHIR, et le classe. Trois formats, une mesure, et chaque étape visible dans la trace.","nl":"De volledige keten zoals een ziekenhuis die draait. Een monitor publiceert een meting via MQTT, de motor decodeert het bericht naar een ORU^R01 - wat een echte monitor verstuurt - vertaalt dat naar een FHIR Observation en slaat het op. Drie formaten, één meting, elke stap zichtbaar in het spoor."}'::jsonb, true, '[{"id":"n-mqtt-src","type":"mqttSource","label":"hospital/ward/#","x":60.0,"y":180.0,"config":{"filter":"hospital/ward/#"}},{"id":"n-mqtt-oru","type":"deviceDecoder","label":"ORU^R01","x":300.0,"y":180.0,"config":{"format":"hl7v2"}},{"id":"n-mqtt-fhir","type":"hl7ToFhir","label":"v2 → FHIR","x":540.0,"y":180.0,"config":{"target":"observation"}},{"id":"n-mqtt-store","type":"fhirStore","label":"FHIR server","x":800.0,"y":90.0,"config":{}},{"id":"n-mqtt-ehr","type":"applicationDestination","label":"EHR","x":800.0,"y":270.0,"config":{"app":"EHR"}}]'::jsonb, '[{"id":"c-mqtt-1","from_node_id":"n-mqtt-src","to_node_id":"n-mqtt-oru","from_port":"out"},{"id":"c-mqtt-2","from_node_id":"n-mqtt-oru","to_node_id":"n-mqtt-fhir","from_port":"out"},{"id":"c-mqtt-3","from_node_id":"n-mqtt-fhir","to_node_id":"n-mqtt-store","from_port":"out"},{"id":"c-mqtt-4","from_node_id":"n-mqtt-fhir","to_node_id":"n-mqtt-ehr","from_port":"out"}]'::jsonb, now(), 5127, 11);
INSERT INTO integration_flows (id, name, description, is_enabled, nodes, connections, updated_at, messages_processed, messages_failed) VALUES ('flow-hl7-adt', '{"en":"HL7 v2 admissions to FHIR","fr":"Admissions HL7 v2 vers FHIR","nl":"HL7 v2-opnames naar FHIR"}'::jsonb, '{"en":"The job an interface engine does all day: an ADT^A01 arrives as a pipe-delimited v2 message, its segments are parsed, inpatient admissions are kept, and the visit is translated into a FHIR Encounter for the record. Open a message and switch between the two views to see what each format keeps and what it loses.","fr":"Le travail quotidien d''un moteur d''intégration : un ADT^A01 arrive en message v2 à barres verticales, ses segments sont analysés, les admissions hospitalières sont retenues, et le séjour est traduit en Encounter FHIR pour le dossier. Ouvrez un message et basculez entre les deux vues pour voir ce que chaque format conserve et ce qu''il perd.","nl":"Het dagelijkse werk van een integratiemotor: een ADT^A01 komt binnen als v2-bericht met pipes, de segmenten worden ontleed, opnames worden behouden en het verblijf wordt vertaald naar een FHIR Encounter voor het dossier. Open een bericht en wissel tussen beide weergaven om te zien wat elk formaat bewaart en verliest."}'::jsonb, true, '[{"id":"n-hl7-src","type":"hl7Source","label":"ADT^A01 in","x":60.0,"y":180.0,"config":{"path":"hl7"}},{"id":"n-hl7-filter","type":"filter","label":"Inpatient only","x":300.0,"y":180.0,"config":{"path":"PV1.2","operator":"equals","value":"I"}},{"id":"n-hl7-fhir","type":"hl7ToFhir","label":"v2 → FHIR","x":540.0,"y":180.0,"config":{"target":"encounter"}},{"id":"n-hl7-store","type":"fhirStore","label":"FHIR server","x":800.0,"y":90.0,"config":{}},{"id":"n-hl7-ehr","type":"applicationDestination","label":"EHR","x":800.0,"y":270.0,"config":{"app":"EHR"}}]'::jsonb, '[{"id":"c-hl7-1","from_node_id":"n-hl7-src","to_node_id":"n-hl7-filter","from_port":"out"},{"id":"c-hl7-2","from_node_id":"n-hl7-filter","to_node_id":"n-hl7-fhir","from_port":"out"},{"id":"c-hl7-3","from_node_id":"n-hl7-fhir","to_node_id":"n-hl7-store","from_port":"out"},{"id":"c-hl7-4","from_node_id":"n-hl7-fhir","to_node_id":"n-hl7-ehr","from_port":"out"}]'::jsonb, now() - interval '86400 seconds', 342, 2);
INSERT INTO integration_flows (id, name, description, is_enabled, nodes, connections, updated_at, messages_processed, messages_failed) VALUES ('flow-vitals', '{"en":"Device vitals to the record","fr":"Signes vitaux vers le dossier","nl":"Vitale functies naar het dossier"}'::jsonb, '{"en":"Takes every reading the connected devices publish, checks it is valid FHIR, adds the patient demographics, then stores it on the FHIR server and pushes it to the EHR.","fr":"Reçoit chaque mesure publiée par les appareils connectés, vérifie qu''il s''agit de FHIR valide, ajoute les données démographiques du patient, puis stocke la ressource sur le serveur FHIR et la transmet à l''EHR.","nl":"Ontvangt elke meting van de aangesloten apparaten, controleert of het geldige FHIR is, voegt de demografische gegevens van de patiënt toe en slaat de resource op de FHIR-server op en stuurt ze naar het EPD."}'::jsonb, true, '[{"id":"n-vitals-src","type":"deviceSource","label":"Device feed","x":60.0,"y":180.0,"config":{}},{"id":"n-vitals-val","type":"validator","label":"Valid FHIR?","x":300.0,"y":180.0,"config":{}},{"id":"n-vitals-enr","type":"enricher","label":"Add patient","x":540.0,"y":180.0,"config":{"path":"subject.reference","target":"patient"}},{"id":"n-vitals-fhir","type":"fhirStore","label":"FHIR server","x":800.0,"y":90.0,"config":{}},{"id":"n-vitals-ehr","type":"applicationDestination","label":"EHR","x":800.0,"y":270.0,"config":{"app":"EHR"}}]'::jsonb, '[{"id":"c-vitals-1","from_node_id":"n-vitals-src","to_node_id":"n-vitals-val","from_port":"out"},{"id":"c-vitals-2","from_node_id":"n-vitals-val","to_node_id":"n-vitals-enr","from_port":"out"},{"id":"c-vitals-3","from_node_id":"n-vitals-enr","to_node_id":"n-vitals-fhir","from_port":"out"},{"id":"c-vitals-4","from_node_id":"n-vitals-enr","to_node_id":"n-vitals-ehr","from_port":"out"}]'::jsonb, now() - interval '259200 seconds', 1284, 6);
INSERT INTO integration_flows (id, name, description, is_enabled, nodes, connections, updated_at, messages_processed, messages_failed) VALUES ('flow-adt', '{"en":"ADT movements fan-out","fr":"Diffusion des mouvements ADT","nl":"Verspreiding van ADT-bewegingen"}'::jsonb, '{"en":"Routes each admission, transfer and discharge to the systems that care about it. An admission opens the record in the EHR; a discharge tells the pharmacy to close the prescriptions.","fr":"Achemine chaque admission, transfert et sortie vers les systèmes concernés. Une admission ouvre le dossier dans l''EHR ; une sortie demande à la pharmacie de clôturer les prescriptions.","nl":"Stuurt elke opname, overplaatsing en ontslag naar de systemen die ze nodig hebben. Een opname opent het dossier in het EPD; een ontslag laat de apotheek de voorschriften afsluiten."}'::jsonb, true, '[{"id":"n-adt-src","type":"adtSource","label":"ADT events","x":60.0,"y":200.0,"config":{}},{"id":"n-adt-route","type":"router","label":"By movement type","x":300.0,"y":200.0,"config":{"path":"type","routes":[{"value":"admission","port":"admission"},{"value":"transfer","port":"transfer"},{"value":"discharge","port":"discharge"}],"defaultPort":"admission"}},{"id":"n-adt-ehr","type":"applicationDestination","label":"EHR: open record","x":600.0,"y":60.0,"config":{"app":"EHR"}},{"id":"n-adt-bed","type":"applicationDestination","label":"EHR: update location","x":600.0,"y":200.0,"config":{"app":"EHR"}},{"id":"n-adt-pharm","type":"applicationDestination","label":"PHARM: close orders","x":600.0,"y":340.0,"config":{"app":"PHARM"}}]'::jsonb, '[{"id":"c-adt-1","from_node_id":"n-adt-src","to_node_id":"n-adt-route","from_port":"out"},{"id":"c-adt-2","from_node_id":"n-adt-route","to_node_id":"n-adt-ehr","from_port":"admission"},{"id":"c-adt-3","from_node_id":"n-adt-route","to_node_id":"n-adt-bed","from_port":"transfer"},{"id":"c-adt-4","from_node_id":"n-adt-route","to_node_id":"n-adt-pharm","from_port":"discharge"}]'::jsonb, now() - interval '86400 seconds', 342, 2);
INSERT INTO integration_flows (id, name, description, is_enabled, nodes, connections, updated_at, messages_processed, messages_failed) VALUES ('flow-spo2-alert', '{"en":"Low SpO2 alert","fr":"Alerte SpO2 basse","nl":"Alarm lage SpO2"}'::jsonb, '{"en":"Watches the oxygen saturation readings and raises an alert when one drops below 92%. Everything else is dropped, so the alert channel stays quiet until it matters.","fr":"Surveille les mesures de saturation en oxygène et déclenche une alerte lorsque l''une d''elles descend sous 92 %. Le reste est écarté, afin que le canal d''alerte reste silencieux tant qu''il n''y a rien à signaler.","nl":"Bewaakt de zuurstofsaturatiemetingen en slaat alarm zodra er een onder 92% zakt. De rest wordt weggefilterd, zodat het alarmkanaal stil blijft tot het ertoe doet."}'::jsonb, true, '[{"id":"n-spo2-src","type":"deviceSource","label":"Device feed","x":60.0,"y":160.0,"config":{}},{"id":"n-spo2-is","type":"filter","label":"Is it SpO2?","x":280.0,"y":160.0,"config":{"path":"code.coding.0.code","operator":"equals","value":"2708-6"}},{"id":"n-spo2-low","type":"filter","label":"Below 92%?","x":520.0,"y":160.0,"config":{"path":"valueQuantity.value","operator":"lessThan","value":"92"}},{"id":"n-spo2-map","type":"mapper","label":"Build alert","x":760.0,"y":160.0,"config":{"mappings":[{"source":"","target":"severity","transform":"constant","argument":"high"},{"source":"subject.reference","target":"patient","transform":"stripPrefix","argument":"Patient/"},{"source":"valueQuantity.value","target":"spo2","transform":"toNumber"},{"source":"effectiveDateTime","target":"measuredAt","transform":"none"},{"source":"device.reference","target":"device","transform":"stripPrefix","argument":"Device/"}]}},{"id":"n-spo2-log","type":"logDestination","label":"Alert log","x":1000.0,"y":160.0,"config":{}}]'::jsonb, '[{"id":"c-spo2-1","from_node_id":"n-spo2-src","to_node_id":"n-spo2-is","from_port":"out"},{"id":"c-spo2-2","from_node_id":"n-spo2-is","to_node_id":"n-spo2-low","from_port":"out"},{"id":"c-spo2-3","from_node_id":"n-spo2-low","to_node_id":"n-spo2-map","from_port":"out"},{"id":"c-spo2-4","from_node_id":"n-spo2-map","to_node_id":"n-spo2-log","from_port":"out"}]'::jsonb, now() - interval '18000 seconds', 1284, 0);
